Object.assign(SNIP,{});PRESET_NOTES["l69"]={"Ví dụ: Thao tác bit trên tập hợp": "{0, 3, 4} ↔ 2^0 + 2^3 + 2^4 = 25. Bỏ 3 còn 17. Tám tập con của {0, 1, 2} ứng với s = 0 … 7.", "Ví dụ: Duyệt mọi tập con": "Có 2 cách tiêu vừa đúng 12: {3, 9} và {5, 7}. Mỗi mask là một cách chọn; tổng chi phí O(2^n · n) — n = 20 khoảng 20 triệu bước.", "Ví dụ: Người du lịch": "Vòng tối ưu 0 → 1 → 3 → 2 → 0 dài 10 + 25 + 30 + 15 = 80. Bảng dp có 2^4 · 4 = 64 ô.", "Ví dụ: Phân công việc": "Người thứ k luôn là người nhận việc kế tiếp, nên chỉ cần mask các việc đã giao: 2^n trạng thái thay vì n!. Tối ưu: người 0 làm việc 1 (2), người 1 làm việc 0 (6), người 2 làm việc 2 (1): tổng 9.", "Lỗi: dùng ^ như phép lũy thừa": "In 1. Toán tử ^ là XOR bit: 2 ^ 3 = 010 XOR 011 = 001. Số tập con viết là 1 << n."};EX_HINTS["l69"]=[["W tới 10^9 nên bảng QHĐ cái túi theo khối lượng (bài 47) quá lớn; nhưng n ≤ 20 nên 2^20 ≈ 10^6 tập con là duyệt được.", "Mỗi mask là một cách chọn: bit i bật thì lấy món i. Cộng khối lượng và giá trị các món được chọn.", "Tổng có thể vượt int: dùng long long."], ["dp[mask][v] = thời gian nhỏ nhất xuất phát từ 0, đã ghé đúng tập mask, đang ở v. Khởi tạo dp[1][0] = 0 (mask = 1 là tập {0}).", "Duyệt mask tăng dần; từ (mask, v) đi tới u chưa có trong mask: cập nhật dp[mask | (1 << u)][u].", "Đáp án: min dp[(1 << n) − 1][v] + d[v][0] với v ≠ 0. Trường hợp n = 1: 0. Thử mọi hoán vị tốn (n − 1)! — với n = 15 là 87 tỉ."], ["Giao ca lần lượt cho nhân viên 0, 1, 2, …: khi tập ca đã giao là mask thì người tiếp theo là số bit bật của mask.", "dp[mask] = chi phí nhỏ nhất; từ mask thử giao ca j chưa có trong mask cho người tiếp theo. Đáp án dp[(1 << n) − 1].", "Đếm bit: __builtin_popcount(mask), hoặc tự đếm bằng vòng lặp. Thử mọi hoán vị tốn n! — với n = 16 là 2·10^13."]];
/* ===================== BÀI 69 · Quy hoạch động trạng thái bit (bitmask) ===================== */
/* Bài 69 · Quy hoạch động trạng thái bit (bitmask)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR69=[{label:"Ví dụ: Thao tác bit trên tập hợp",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int mask = 0;\n    mask |= 1 << 0;                    // thêm 0\n    mask |= 1 << 3;                    // thêm 3\n    mask |= 1 << 4;                    // thêm 4: mask = 11001 (nhị phân) = 25\n    cout << mask << \" \" << ((mask >> 3) & 1) << \" \" << ((mask >> 1) & 1) << \"\\n\";\n    mask &= ~(1 << 3);                 // bỏ 3\n    cout << mask << \"\\n\";\n    int n = 3;\n    for (int s = 0; s < (1 << n); s++) {   // mọi tập con của {0, 1, 2}\n        cout << \"{\";\n        for (int i = 0; i < n; i++)\n            if ((s >> i) & 1) cout << \" \" << i;\n        cout << \" } \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["mask","s","i"]}],py:{code:"mask = 0\nmask |= 1 << 0                         # thêm 0\nmask |= 1 << 3                         # thêm 3\nmask |= 1 << 4                         # thêm 4: mask = 0b11001 = 25\nprint(mask, (mask >> 3) & 1, (mask >> 1) & 1)\nmask &= ~(1 << 3)                      # bỏ 3\nprint(mask)\nn = 3\ndong = []\nfor s in range(1 << n):                # mọi tập con của {0, 1, 2}\n    dong.append(\"{\" + \"\".join(\" \" + str(i) for i in range(n) if (s >> i) & 1) + \" }\")\nprint(\" \".join(dong))"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int mask = 0;\n        mask |= 1 << 0;                        // thêm 0\n        mask |= 1 << 3;                        // thêm 3\n        mask |= 1 << 4;                        // thêm 4: mask = 11001 (nhị phân) = 25\n        Console.WriteLine(mask + \" \" + ((mask >> 3) & 1) + \" \" + ((mask >> 1) & 1));\n        mask &= ~(1 << 3);                     // bỏ 3\n        Console.WriteLine(mask);\n        int n = 3;\n        for (int s = 0; s < (1 << n); s++)     // mọi tập con của {0, 1, 2}\n        {\n            Console.Write(\"{\");\n            for (int i = 0; i < n; i++)\n                if (((s >> i) & 1) == 1) Console.Write(\" \" + i);\n            Console.Write(\" } \");\n        }\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Duyệt mọi tập con",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> gia = {3, 5, 7, 9};    // giá 4 món, ngân sách 12\n    int n = gia.size(), nganSach = 12, dem = 0, tot = -1, tapTot = 0;\n    for (int mask = 0; mask < (1 << n); mask++) {\n        int tong = 0;\n        for (int i = 0; i < n; i++)\n            if ((mask >> i) & 1) tong += gia[i];\n        if (tong == nganSach) dem++;   // tiêu vừa hết ngân sách\n        if (tong <= nganSach && tong > tot) { tot = tong; tapTot = mask; }\n    }\n    cout << dem << \" \" << tot << \" \" << tapTot << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"gia",ptr:["i"]},{type:"vars",names:["mask","tong","dem"]}],py:{code:"gia = [3, 5, 7, 9]                     # giá 4 món, ngân sách 12\nn, ngan_sach = len(gia), 12\ndem, tot, tap_tot = 0, -1, 0\nfor mask in range(1 << n):\n    tong = 0\n    for i in range(n):\n        if (mask >> i) & 1:\n            tong += gia[i]\n    if tong == ngan_sach:              # tiêu vừa hết ngân sách\n        dem += 1\n    if tong <= ngan_sach and tong > tot:\n        tot, tap_tot = tong, mask\nprint(dem, tot, tap_tot)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] gia = { 3, 5, 7, 9 };            // giá 4 món, ngân sách 12\n        int n = gia.Length, nganSach = 12, dem = 0, tot = -1, tapTot = 0;\n        for (int mask = 0; mask < (1 << n); mask++)\n        {\n            int tong = 0;\n            for (int i = 0; i < n; i++)\n                if (((mask >> i) & 1) == 1) tong += gia[i];\n            if (tong == nganSach) dem++;       // tiêu vừa hết ngân sách\n            if (tong <= nganSach && tong > tot) { tot = tong; tapTot = mask; }\n        }\n        Console.WriteLine(dem + \" \" + tot + \" \" + tapTot);\n    }\n}"}},{label:"Ví dụ: Người du lịch",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n = 4;\n    vector<vector<int>> d = {{0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};\n    const int INF = 1e9;\n    vector<vector<int>> dp(1 << n, vector<int>(n, INF));\n    dp[1][0] = 0;                      // đã ghé {0}, đang ở 0\n    for (int mask = 1; mask < (1 << n); mask++)\n        for (int v = 0; v < n; v++) {\n            if (dp[mask][v] == INF) continue;\n            for (int u = 0; u < n; u++)\n                if (!((mask >> u) & 1)) {   // u chưa ghé\n                    int moi = mask | (1 << u);\n                    dp[moi][u] = min(dp[moi][u], dp[mask][v] + d[v][u]);\n                }\n        }\n    int tot = INF;\n    for (int v = 1; v < n; v++) tot = min(tot, dp[(1 << n) - 1][v] + d[v][0]);   // quay về 0\n    cout << tot << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["mask","v","u","moi","tot"]}],py:{code:"n = 4\nd = [[0, 10, 15, 20], [10, 0, 35, 25], [15, 35, 0, 30], [20, 25, 30, 0]]\nINF = float(\"inf\")\ndp = [[INF] * n for _ in range(1 << n)]\ndp[1][0] = 0                           # đã ghé {0}, đang ở 0\nfor mask in range(1, 1 << n):\n    for v in range(n):\n        if dp[mask][v] == INF:\n            continue\n        for u in range(n):\n            if not (mask >> u) & 1:    # u chưa ghé\n                moi = mask | (1 << u)\n                dp[moi][u] = min(dp[moi][u], dp[mask][v] + d[v][u])\ntot = min(dp[(1 << n) - 1][v] + d[v][0] for v in range(1, n))   # quay về 0\nprint(tot)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 4;\n        int[][] d = { new[] { 0, 10, 15, 20 }, new[] { 10, 0, 35, 25 }, new[] { 15, 35, 0, 30 }, new[] { 20, 25, 30, 0 } };\n        const int INF = 1000000000;\n        int[][] dp = new int[1 << n][];\n        for (int m = 0; m < (1 << n); m++) { dp[m] = new int[n]; for (int v = 0; v < n; v++) dp[m][v] = INF; }\n        dp[1][0] = 0;                          // đã ghé {0}, đang ở 0\n        for (int mask = 1; mask < (1 << n); mask++)\n            for (int v = 0; v < n; v++)\n            {\n                if (dp[mask][v] == INF) continue;\n                for (int u = 0; u < n; u++)\n                    if (((mask >> u) & 1) == 0)    // u chưa ghé\n                    {\n                        int moi = mask | (1 << u);\n                        dp[moi][u] = Math.Min(dp[moi][u], dp[mask][v] + d[v][u]);\n                    }\n            }\n        int tot = INF;\n        for (int v = 1; v < n; v++) tot = Math.Min(tot, dp[(1 << n) - 1][v] + d[v][0]);   // quay về 0\n        Console.WriteLine(tot);\n    }\n}"}},{label:"Ví dụ: Phân công việc",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n = 3;\n    vector<vector<int>> c = {{9, 2, 7}, {6, 4, 3}, {5, 8, 1}};   // c[người][việc]\n    const int INF = 1e9;\n    vector<int> dp(1 << n, INF);       // dp[mask]: các việc trong mask đã giao cho những người đầu tiên\n    dp[0] = 0;\n    for (int mask = 0; mask < (1 << n); mask++) {\n        if (dp[mask] == INF) continue;\n        int nguoi = __builtin_popcount(mask);   // người tiếp theo = số việc đã giao\n        if (nguoi == n) continue;\n        for (int j = 0; j < n; j++)\n            if (!((mask >> j) & 1))\n                dp[mask | (1 << j)] = min(dp[mask | (1 << j)], dp[mask] + c[nguoi][j]);\n    }\n    cout << dp[(1 << n) - 1] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["mask"]},{type:"vars",names:["mask","nguoi","j"]}],py:{code:"n = 3\nc = [[9, 2, 7], [6, 4, 3], [5, 8, 1]]  # c[người][việc]\nINF = float(\"inf\")\ndp = [INF] * (1 << n)                  # dp[mask]: các việc trong mask đã giao cho những người đầu tiên\ndp[0] = 0\nfor mask in range(1 << n):\n    if dp[mask] == INF:\n        continue\n    nguoi = bin(mask).count(\"1\")       # người tiếp theo = số việc đã giao\n    if nguoi == n:\n        continue\n    for j in range(n):\n        if not (mask >> j) & 1:\n            dp[mask | (1 << j)] = min(dp[mask | (1 << j)], dp[mask] + c[nguoi][j])\nprint(dp[(1 << n) - 1])"},cs:{code:"using System;\n\nclass Program\n{\n    static int SoBit(int x)                // đếm số bit bật\n    {\n        int c = 0;\n        while (x > 0) { c += x & 1; x >>= 1; }\n        return c;\n    }\n\n    static void Main()\n    {\n        int n = 3;\n        int[][] c = { new[] { 9, 2, 7 }, new[] { 6, 4, 3 }, new[] { 5, 8, 1 } };   // c[người][việc]\n        const int INF = 1000000000;\n        int[] dp = new int[1 << n];            // dp[mask]: các việc trong mask đã giao cho những người đầu tiên\n        for (int m = 1; m < (1 << n); m++) dp[m] = INF;\n        for (int mask = 0; mask < (1 << n); mask++)\n        {\n            if (dp[mask] == INF) continue;\n            int nguoi = SoBit(mask);           // người tiếp theo = số việc đã giao\n            if (nguoi == n) continue;\n            for (int j = 0; j < n; j++)\n                if (((mask >> j) & 1) == 0)\n                    dp[mask | (1 << j)] = Math.Min(dp[mask | (1 << j)], dp[mask] + c[nguoi][j]);\n        }\n        Console.WriteLine(dp[(1 << n) - 1]);\n    }\n}",note:"Người thứ k luôn là người nhận việc kế tiếp, nên chỉ cần mask các việc đã giao: 2^n trạng thái thay vì n!. Tối ưu: người 0 làm việc 1 (2), người 1 làm việc 0 (6), người 2 làm việc 2 (1): tổng 9."}},{label:"Lỗi: dùng ^ như phép lũy thừa",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n = 3, dem = 0;\n    for (int mask = 0; mask < (2 ^ n); mask++) dem++;   // SAI: 2 ^ 3 là XOR = 1, không phải 8\n    cout << dem << \"\\n\";               // đúng phải là 8 tập con\n    return 0;\n}",viz:[{type:"vars",names:["n","mask","dem"]}],py:{code:"n = 3\ndem = 0\nfor mask in range(2 ^ n):              # SAI: 2 ^ 3 là XOR = 1, không phải 8\n    dem += 1\nprint(dem)                             # đúng phải là 8 tập con",note:"In 1. Toán tử ^ là XOR bit: 2 ^ 3 = 0b010 XOR 0b011 = 0b001. Số tập con viết là 1 << n (hoặc 2 ** n)."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 3, dem = 0;\n        for (int mask = 0; mask < (2 ^ n); mask++) dem++;   // SAI: 2 ^ 3 là XOR = 1, không phải 8\n        Console.WriteLine(dem);                // đúng phải là 8 tập con\n    }\n}"}}];
